647	      const next = new Set(ids);
648	      if (t.on) next.add(t.id);
649	      else next.delete(t.id);
650	      return next;
651	    });
652	  }
653	
654	  /** Open every selected claim that can be opened, numbered in list order; then show how many
655	   *  were opened and refused, and the claims as the store now holds them. */
656	  protected async bulkOpen(): Promise<void> {
657	    if (this.bulkOpening) return;
658	    this.bulkResult.set(null);
659	    this.bulkError.set(null);
660	    const sheetId = this.session.sheetId();
661	    if (!sheetId) return;
662	    const ids = [...this.selectedClaims()];
663	    this.bulkOpening = true;
664	    try {
665	      const result = await this.claimsApi.bulkOpen(sheetId, ids);
666	      const claims = await this.claimsApi.list(sheetId);
667	      if (this.session.sheetId() !== sheetId) return;
668	      this.claims.set(claims);
669	      this.selectedClaims.set(new Set());
670	      this.bulkResult.set(result);
671	    } catch {
672	      this.bulkError.set('Something went wrong opening the claims; try again.');
673	    } finally {
674	      this.bulkOpening = false;
675	    }
676	  }
677	
678	  /** Settle every selected claim that can be settled, in list order, by the rules of settling one
679	   *  (one sent to PENDING counts as settled); then show how many were settled and refused, and the
680	   *  claims as the store now holds them. */
681	  protected async bulkSettle(): Promise<void> {
682	    if (this.bulkSettling) return;
683	    this.bulkSettleResult.set(null);
684	    this.bulkSettleError.set(null);
685	    const sheetId = this.session.sheetId();
686	    if (!sheetId) return;
687	    const ids = [...this.selectedClaims()];
688	    this.bulkSettling = true;
689	    try {
690	      const result = await this.claimsApi.bulkSettle(sheetId, ids);
691	      const claims = await this.claimsApi.list(sheetId);
692	      if (this.session.sheetId() !== sheetId) return;
693	      this.claims.set(claims);
694	      this.selectedClaims.set(new Set());
695	      this.bulkSettleResult.set(result);
696	    } catch {
697	      this.bulkSettleError.set('Something went wrong settling the claims; try again.');
698	    } finally {
699	      this.bulkSettling = false;
700	    }
701	  }
702	
703	  /** Download the people as CSV, in list order, retired ones too: name, grade today, retired-from, due-total as shown. */
704	  protected exportCsv(): void {
705	    const lines = [csvLine(['name', 'grade', 'retired-from', 'due-total']),
706	      ...this.people().map((p) => csvLine([p.name, this.gradeOf(p), p.retiredFrom ?? '', this.dueOf(p)]))];
707	    const url = URL.createObjectURL(new Blob([lines.join('')], { type: 'text/csv' }));
708	    const link = this.document.createElement('a');
709	    link.href = url;
710	    link.download = `people-${this.session.sheetId()}.csv`;
711	    link.click();
712	    setTimeout(() => URL.revokeObjectURL(url));
713	  }
714	
715	  protected cancel(): void {
716	    this.reset();
717	  }
718	
719	  protected async submit(): Promise<void> {
720	    if (this.submitting) return;
721	    this.error.set(null);
722	    const sheetId = this.session.sheetId();
723	    if (!sheetId) return;
724	    const value = this.form.getRawValue();
725	    if (!value.name.trim()) {
726	      this.error.set('Enter a name.');
727	      return;
728	    }
729	    if (!(GRADES as readonly string[]).includes(value.grade)) {
730	      this.error.set('Choose a grade.');
731	      return;
732	    }
733	    if (!/^\d{0,4}$/.test(value.terms.trim())) {
734	      // refused terms leave the editor, so the form is ready to add a person next
735	      this.reset();
736	      this.error.set('Enter terms as whole days, or leave them blank for none.');
737	      return;
738	    }
739	    const editing = this.editingId();
740	    this.submitting = true;
741	    try {
742	      if (editing === null) {
743	        const added = await this.api.add(sheetId, { name: value.name, grade: value.grade, terms: value.terms.trim() });
744	        if (this.session.sheetId() === sheetId) this.people.update((ps) => [...ps, added]);
745	      } else {
746	        const saved = await this.api.update(sheetId, editing,
747	          { ...value, gradeFrom: value.gradeFrom.trim() || null, terms: value.terms.trim(), version: this.editingVersion });
748	        if (this.session.sheetId() === sheetId) this.taken(saved);
749	      }
750	      this.reset();
751	    } catch (e) {
752	      if (editing !== null && isStale(e)) await this.reloadEditing(sheetId, editing);
753	      this.error.set(personError(e));
754	    } finally {
755	      this.submitting = false;
756	    }
757	  }
758	
759	  /** Quick-add a DRAFT claim by name; the person is added first (grade A) when new. */
760	  protected async quickAdd(): Promise<void> {
761	    if (this.quickAdding) return;
762	    this.quickError.set(null);
763	    const sheetId = this.session.sheetId();
764	    if (!sheetId) return;
765	    const value = this.quickForm.getRawValue();
766	    const amount = value.amount.trim();
767	    if (!value.name.trim()) {
768	      this.quickError.set('Enter a name.');
769	      return;
770	    }
771	    if (!AMOUNT_PATTERN.test(amount)) {
772	      this.quickError.set('Enter an amount of 0.00 or more with up to two decimals.');
773	      return;
774	    }
775	    this.quickAdding = true;
776	    try {
777	      const added = await this.claimsApi.quickAdd(sheetId, { name: value.name, amount });
778	      if (this.session.sheetId() !== sheetId) return;
779	      if (added.personAdded) this.people.update((ps) => [...ps.filter((p) => p.id !== added.person.id), added.person]);
780	      else this.taken(added.person);
781	      this.claimSaved(added.claim);
782	      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
783	    } catch (e) {
784	      this.quickError.set(quickAddError(e));
785	    } finally {
786	      this.quickAdding = false;
787	    }
788	  }
789	
790	  /** Add a DRAFT claim per pasted line, all or none; then show how many were added. */
791	  protected async paste(): Promise<void> {
792	    if (this.pasting) return;
793	    this.pasted.set(null);
794	    this.pasteErr.set(null);
795	    const sheetId = this.session.sheetId();
796	    if (!sheetId) return;
797	    const text = this.pasteForm.getRawValue().text;
798	    if (!text.trim()) {
799	      this.pasteErr.set('Paste at least one line of name,amount,date,note.');
800	      return;
801	    }
802	    this.pasting = true;
803	    try {
804	      const added = await this.claimsApi.paste(sheetId, text);
805	      if (this.session.sheetId() !== sheetId) return;
806	      for (const claim of added) this.claimSaved(claim);
807	      this.pasteForm.reset({ text: '' }, { emitEvent: false });
808	      this.pasted.set(added.length);
809	    } catch (e) {
810	      this.pasteErr.set(pasteError(e));
811	    } finally {
812	      this.pasting = false;
813	    }
814	  }
815	
816	  /** Take in a person as the store now holds them, in place of the old row. */
817	  private taken(person: Person): void {
818	    this.people.update((ps) => ps.map((p) => (p.id === person.id ? person : p)));
819	  }
820	
821	  /** After a save refused as stale, show the person's current values in the row and the open
822	   *  editor, which then edits that version. */
823	  private async reloadEditing(sheetId: string, id: number): Promise<void> {
824	    try {
825	      const current = await this.api.get(sheetId, id);
826	      if (this.session.sheetId() !== sheetId || this.editingId() !== id) return;
827	      this.taken(current);
828	      this.editingVersion = current.version;
829	      this.form.setValue({ name: current.name, grade: this.gradeOf(current), gradeFrom: this.form.getRawValue().gradeFrom,
830	        terms: termsText(current) },
831	        { emitEvent: false });
832	    } catch {
833	      // the error shown already says the save was refused
834	    }
835	  }
836	
837	  private reset(): void {
838	    this.editingId.set(null);
839	    this.form.reset({ name: '', grade: 'A', gradeFrom: '', terms: '' });
840	    this.error.set(null);
841	  }
842	
843	  private async read(sheetId: string): Promise<void> {
844	    const seq = ++this.readSeq;
845	    try {
846	      const [people, claims, rates, periods] = await Promise.all([
847	        this.api.list(sheetId), this.claimsApi.list(sheetId), this.ratesApi.list(sheetId), this.periodsApi.list(sheetId)]);
848	      if (seq === this.readSeq) {
849	        this.rates.set(rates);
850	        this.periods.set(periods);
851	        this.claims.set(claims);
852	        this.people.set(people);
853	      }
854	    } catch {
855	      if (seq === this.readSeq) this.error.set('Something went wrong loading people; try again.');
856	    }
857	  }
858	}
859	
860	/** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
861	function trimmedSum(figures: number[]): number {
862	  const sum = figures.reduce((a, b) => a + b, 0);
863	  return figures.length < 3 ? sum : sum - Math.max(...figures) - Math.min(...figures);
864	}
865	
866	/** A person's own terms as the form shows them: the days, blank when none. */
867	function termsText(p: Person): string {
868	  return p.terms === null ? '' : String(p.terms);
869	}
